export function ProgressiveDisclosure({
  heading = "{{heading}}",
  summaryText = "{{summaryText}}",
  accent = "{{accent}}",
  defaultOpen = {{defaultOpen}},
  detailLevel = "{{detailLevel}}",
}) {
  const showAdvanced = detailLevel === "advanced" || detailLevel === "expert";
  const showExpert = detailLevel === "expert";
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 13.5, color: "#241430", background: "#FAF7F2", maxWidth: 320, width: 320, padding: 16, borderRadius: 12, boxSizing: "border-box" }}>
      <h3 style={{ margin: "0 0 10px", fontSize: 15, fontWeight: 700 }}>{heading}</h3>
      <details open={defaultOpen} style={{ background: "#fff", borderRadius: 10, padding: "10px 12px", border: "1px solid #24143020" }}>
        <summary style={{ cursor: "pointer", fontWeight: 700, color: accent }}>{summaryText}</summary>
        <p style={{ margin: "8px 0 0" }}>Standard sharing: view or edit access.</p>
        {showAdvanced && <p style={{ margin: "8px 0 0" }}>Advanced: set link expiry and domain restrictions.</p>}
        {showExpert && <p style={{ margin: "8px 0 0" }}>Expert: enforce SSO and audit every access event.</p>}
      </details>
    </div>
  );
}
